    insert into public.rules (rule_set_id, code, expression, outcome, reason_code, reason_en, reason_ur) values ('aad87c09-bb64-4e24-8630-5b1d062cdb87', 'R0_PMT_CLEARLY_ELIGIBLE', '{"and":[{"!":{"missing":["household.pmt_score"]}},{"<=":[{"var":"household.pmt_score"},25]}]}'::jsonb, 'PASS', 'R_AUTO_APPROVED', 'Your claim matches the rules. Your payment is approved and the amount has been sent to your account.', 'آپ کا دعویٰ قواعد پر پورا اترتا ہے۔ آپ کی ادائیگی منظور ہو گئی ہے اور رقم آپ کے اکاؤنٹ میں بھیج دی گئی ہے۔');
